using Ohno.CircleGame.Gameplay;
namespace Ohno.QA11;
public static partial class Tests
{
    sealed record Op(string Name,int Handle,int Attribute=0,float Value=0,bool? Flag=null);
    sealed class Backend:IPersistentSampleChannels
    {
        public List<Op> Ops{get;}=[];
        public Dictionary<int,int> States{get;}=[];
        public Queue<int> Handles{get;}=new([101,202,301,402,501,602,701,802]);
        public Action<Op>? Enter{get;set;}
        public Func<int,bool,int>? Acquisition{get;set;}
        void Begin(Op op){Ops.Add(op);Obs(new{operation=op,status="attempted"});try{Enter?.Invoke(op);}catch(Exception e){Obs(new{operation=op,status="failed",e.Message});throw;}}
        public int Acquire(int sample,bool onlyNew){var op=new Op("Acquire",sample,Flag:onlyNew);Begin(op);int result=Acquisition?.Invoke(sample,onlyNew)??Handles.Dequeue();Obs(new{operation=op,status="returned",result});return result;}
        public int Activity(int channel){var op=new Op("Activity",channel);Begin(op);int result=States.GetValueOrDefault(channel);Obs(new{operation=op,status="returned",result});return result;}
        public void Attribute(int ch,int attr,float v){Begin(new("Attribute",ch,attr,v));}
        public void Play(int ch,bool restart)=>Begin(new("Play",ch,Flag:restart));
        public void Pause(int ch)=>Begin(new("Pause",ch));
        public void Stop(int ch)=>Begin(new("Stop",ch));
        public void Dispose()=>Begin(new("Dispose",0));
        public void Clear()=>Ops.Clear();
    }
    sealed class Pair
    {
        public Backend B{get;}=new();public SharedSliderChannels M{get;}
        public List<string> Resolved{get;}=[];public Func<int,int,int,int>? Resolver{get;set;}
        public Pair(IEnumerable<SampleTiming>? points=null,bool warm=true)
        {M=new(new GlobalSampleTiming(points??[P()]),B,(r,s,i)=>{Resolved.Add($"{r}:{s}:{i}");Obs(new{resolve=new[]{r,s,i}});return Resolver?.Invoke(r,s,i)??(10000+r*1000+s*100+i);}){EffectVolume=100,UniversalVolume=100};if(warm){M.Clock(0);Clear();}}
        public void Clear(){B.Clear();Resolved.Clear();}
        public void Record()=>Obs(new{M.Channel0,M.Channel1,M.CurrentIndex,M.CurrentBase,M.LastIndex,M.LastBase,M.LastAddition,M.Pending,baseCursor=M.Timing.BaseCursor,allCursor=M.Timing.AllCursor});
    }
    static SampleTiming P(double time=0,int set=1,int index=1,int volume=100,bool u=true,int source=0)=>new(time,set,index,volume,u,source);
    static void Bits(float actual,uint expected){Obs(new{actual,actualBits=BitConverter.SingleToUInt32Bits(actual),expectedBits=expected});Eq(BitConverter.SingleToUInt32Bits(actual),expected);}
    static void Cursors(GlobalSampleTiming t,int b,int a){Eq(t.BaseCursor,b);Eq(t.AllCursor,a);Obs(new{current=t.Current,points=t.Points});}
